  const x=35+this.side*33;R([x,24,0],[x,24,-5],8.4,'steel',24);Ring([x,24,-5],[x,24,-8],7,4.8,'graphite',20);
}
if(part==='rear'){
  B(164,14,-3,42,20,3,'graphite');R([219,36,-2],[219,36,0],2,'amber',12);
