    B(T+.4,base+(H-base)*.72,D-2.4,W/3-.8,.3,2.1,'ivory');
    B(T+.7,base+(H-base)*.72+.3,D-2.2,W/3-1.1,.22,1.9,'clay');
  }
  return [this.geometry,out];
}

